if(!exists('exposure_schedule'))library(creditratingsystem)
ead_error<-function(code,expr){e<-tryCatch({force(expr);NULL},error=identity);stopifnot(inherits(e,'creditratingsystem_error'),identical(e$code,code))}
ead_near<-function(x,y,tol=1e-12)stopifnot(isTRUE(all.equal(x,y,tolerance=tol,check.attributes=FALSE)))
ead_case<-function(timing='AFTER_PERIOD_END_EVENTS')list(contract=list(facility_id='F',currency='EUR',as_of='2024-01-01',drawn_principal=1000,credit_limit=2000,accrued_interest=0),events=list(list(event_id='draw',event_date='2024-01-16',known_at='2024-01-01',sequence=0,kind='DRAW',amount=500),list(event_id='pay',event_date='2024-02-01',known_at='2024-01-01',sequence=0,kind='PRINCIPAL_REPAYMENT',amount=500)),annual_interest_rates=c(.365,.365),period_end_dates=c('2024-02-01','2024-03-01'),day_count='ACT/365F',default_timing=timing,allow_overlimit=FALSE,currency='EUR')
v<-do.call(exposure_schedule,ead_case())$value$schedule;ead_near(v[[1]]$interest_accrued,39);ead_near(v[[1]]$exposure_before_period_end_events,1539);ead_near(v[[1]]$conditional_ead,1039);stopifnot(v[[1]]$undrawn_commitment==1000);ead_near(v[[2]]$interest_accrued,29);ead_near(v[[2]]$conditional_ead,1068);ead_near(do.call(exposure_schedule,ead_case('BEFORE_PERIOD_END_EVENTS'))$value$schedule[[1]]$conditional_ead,1539)
a<-ead_case();a$annual_interest_rates<-c(0,0);a$events<-a$events[2];a$events[[1]]$amount<-1000;stopifnot(do.call(exposure_schedule,a)$value$schedule[[1]]$conditional_ead==0);a$default_timing<-'BEFORE_PERIOD_END_EVENTS';stopifnot(do.call(exposure_schedule,a)$value$schedule[[1]]$conditional_ead==1000)
a<-ead_case();a$events[[3]]<-list(event_id='limit',event_date='2024-02-10',known_at='2024-01-01',sequence=0,kind='LIMIT_CHANGE',amount=900);v<-do.call(exposure_schedule,a)$value$schedule[[2]];stopifnot(v$overlimit_amount==100,v$undrawn_commitment==0)
a<-ead_case();a$contract$credit_limit<-1200;ead_error('EXPOSURE_LIMIT',do.call(exposure_schedule,a));a$allow_overlimit<-TRUE;stopifnot(do.call(exposure_schedule,a)$value$event_ledger[[1]]$principal_after==1500)
a<-ead_case();a$events[[1]]$known_at<-'2024-01-02';ead_error('EXPOSURE_DATE',do.call(exposure_schedule,a));a<-ead_case();a$events[[3]]<-a$events[[1]];a$events[[3]]$event_id<-'duplicate-time';ead_error('EXPOSURE_AMBIGUITY',do.call(exposure_schedule,a))
ccf_dates<-function()list(reference_date='2023-12-01',default_date='2024-01-01',reference_known_at='2023-12-01',default_known_at='2024-01-02',evaluation_cutoff='2024-01-31',currency='EUR')
for(ead in c(70,10,130)){v<-do.call(realized_ccf,c(list(reference_drawn=40,reference_limit=100,ead_at_default=ead),ccf_dates()))$value;stopifnot(v$ccf==(ead-40)/60);ead_near(v$reconstructed_ead,ead)}
for(drawn in c(100,110)){v<-do.call(realized_ccf,c(list(reference_drawn=drawn,reference_limit=100,ead_at_default=110),ccf_dates()))$value;stopifnot(is.null(v$ccf),v$denominator_status=='NO_POSITIVE_UNDRAWN')}
v<-do.call(realized_ccf,c(list(reference_drawn=99,reference_limit=100,ead_at_default=110,minimum_undrawn=1),ccf_dates()))$value;stopifnot(is.null(v$ccf),v$denominator_status=='BELOW_MINIMUM_UNDRAWN');a<-ccf_dates();a$reference_known_at<-'2023-12-02';ead_error('EXPOSURE_DATE',do.call(realized_ccf,c(list(reference_drawn=40,reference_limit=100,ead_at_default=70),a)))
cat('EAD native balance, leap-day and raw CCF cases passed\n')
